-- Daily challenges for 2026-10-15: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-10-15. The routine loads the same rows in
-- re-runnable pieces from tools/challenges_sync.py; the GitHub workflow applies this file once
-- the SUPABASE_DB_URL secret is set.

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('cooking-for-yourself', 'Cooking for Yourself', 'For anyone who lives on takeout, snacks or skipped meals and would like more home-cooked comfort. Each day is one small, low-pressure kitchen step, from stocking a staple to cooking one simple dish, so feeding yourself feels doable and kind.', 'Body', 365, array['Food', 'Self-Care', 'Habits']::text[], 1, '2026-10-15T17:00:00+00:00'::timestamptz),
  ('getting-along-better-with-family', 'Getting Along Better with Family', 'For anyone who loves their family but finds time together tense or tiring. Each day is one small step toward easier conversations, kinder visits and calmer limits, whether your family lives under your roof or across the country.', 'Relationships', 365, array['Family', 'Communication', 'Boundaries']::text[], 1, '2026-10-15T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('cooking-for-yourself', 'getting-along-better-with-family');

